{
  "summary": "Harden the existing URL-shortening API so that only safe, well-formed destinations are accepted, generated short codes remain unique and resolvable, and all client-visible failures are deterministic JSON responses without implementation details.",
  "changeType": "brownfield",
  "functional": [
    "Preserve the existing link-creation and short-code redirect API contracts unless explicitly changed by the clarified requirements.",
    "Validate submitted destination URLs before persistence. Accept only absolute HTTP and HTTPS URLs, reject unsupported schemes such as javascript:, data:, file:, and mailto:, reject missing or malformed hosts, reject embedded user credentials, and enforce the repository's configured maximum URL length.",
    "Generate short codes using the existing generator and verify uniqueness against the link repository before saving. Retry a bounded number of times on collisions; report a controlled server error if a unique code cannot be allocated.",
    "Persist a successfully created link so that its destination and generated code can be retrieved consistently after the creation request completes.",
    "Resolve a valid short code to its stored destination using the existing redirect endpoint and record the existing click/analytics behavior without changing the destination.",
    "Return a consistent JSON error body for invalid input, unknown short codes, code-generation exhaustion, and unexpected request failures. Error responses must not expose stack traces, SQL details, credentials, or internal class names.",
    "Treat codes as exact identifiers, including case, and reject malformed or empty codes without attempting an unsafe lookup."
  ],
  "nonFunctional": [
    "Security: destination validation must prevent execution of non-HTTP protocols and must not accept URLs containing embedded credentials.",
    "Reliability: short-code allocation must be collision-safe and bounded; a collision or persistence failure must never return a success response for a link that cannot be resolved.",
    "Compatibility: existing successful API consumers, redirect behavior, analytics behavior, and configured public-origin handling must remain compatible except where necessary to enforce the safety rules.",
    "Consistency: validation and error handling must produce the same HTTP status and JSON error shape for equivalent failures across all API entry points.",
    "Operational safety: application responses and errors must not disclose secrets or sensitive implementation details; secrets, if required by existing infrastructure, must continue to come from configuration or environment variables."
  ],
  "outOfScope": [
    "Authentication, authorization, per-user ownership, quotas, and administrative link management.",
    "Malware, phishing, reputation, or content scanning of destination URLs.",
    "Changing the public short-code format, adding user-selected aliases, or adding custom domains.",
    "Changing analytics fields, retention, aggregation, or reporting semantics.",
    "Guaranteeing that a destination remains reachable after a link is created.",
    "Changing the persistence technology or introducing a distributed locking system unless collision or concurrency tests demonstrate that the existing repository contract is insufficient.",
    "Changing redirect status-code semantics unless required by the existing API contract or security review."
  ],
  "openQuestions": [
    {
      "question": "What exact threat model is intended by “safer”: protocol and malformed-URL hardening only, or should links to private networks, localhost, IP literals, punycode domains, or known malicious destinations also be blocked?",
      "assumption": "Implement protocol, syntax, credential, and length validation. Do not block private destinations or perform reputation checks because the service redirects clients and does not fetch destination content.",
      "answer": ""
    },
    {
      "question": "What are the authoritative endpoint paths, request fields, response fields, and redirect status code for the existing API?",
      "assumption": "Preserve the routes and JSON contracts documented in docs/api.md and currently implemented by LinkController and RedirectController; add no new public endpoints.",
      "answer": ""
    },
    {
      "question": "Should URL validation canonicalize destinations, or should the original accepted URL be preserved exactly?",
      "assumption": "Preserve the submitted URL after validation, except for normal framework JSON/string handling; do not silently rewrite paths, query parameters, fragments, or host casing.",
      "answer": ""
    },
    {
      "question": "What should happen when code generation repeatedly collides with an existing code?",
      "assumption": "Retry a bounded configurable number of times, then return HTTP 500 with the standard generic error response and do not persist a partial link.",
      "answer": ""
    },
    {
      "question": "Is link creation expected to be idempotent when the same destination is submitted more than once?",
      "assumption": "No. Each successful creation request produces a distinct short code, while concurrent requests must still never produce duplicate codes.",
      "answer": ""
    },
    {
      "question": "Should the service require HTTPS destinations, or are HTTP destinations supported?",
      "assumption": "Support both HTTP and HTTPS for backward compatibility; reject all other schemes.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given a valid absolute HTTP or HTTPS URL within the configured maximum length, when a client calls the existing link-creation endpoint with the documented request shape, then the API returns the existing successful creation status and response shape, including a non-empty short code and short URL, and the link can subsequently be resolved."
    },
    {
      "id": "AC2",
      "criterion": "Given a URL with an unsupported scheme, missing host, invalid syntax, embedded username or password, or a length greater than the configured maximum, when the client submits it to the link-creation endpoint, then the API returns HTTP 400 with the documented JSON error shape, does not create a link, and does not include a stack trace or internal implementation details."
    },
    {
      "id": "AC3",
      "criterion": "Given two or more successful link-creation requests, including concurrent requests with the same destination, when the clients inspect the returned short codes and resolve each code through the redirect endpoint, then every successful response has a distinct code and every returned code redirects to the destination associated with that response."
    },
    {
      "id": "AC4",
      "criterion": "Given an existing short code, when a client requests the existing redirect endpoint, then the API returns the existing redirect status and location behavior for the stored destination, and the request does not substitute a client-supplied destination."
    },
    {
      "id": "AC5",
      "criterion": "Given an empty, malformed, or unknown short code, when a client requests the redirect endpoint, then the API returns the documented not-found or bad-request HTTP status with the standard JSON error shape and does not redirect."
    },
    {
      "id": "AC6",
      "criterion": "Given a short-code collision during creation, when the service can allocate another code within the configured retry limit, then the creation request succeeds with the newly allocated unique code and neither the colliding existing link nor the new link is overwritten."
    },
    {
      "id": "AC7",
      "criterion": "Given that all bounded code-generation attempts fail or persistence fails, when a client submits a valid creation request, then the API returns a generic HTTP 5xx error in the standard JSON error shape and no response claims that an unresolved link was created."
    },
    {
      "id": "AC8",
      "criterion": "Given any handled validation, not-found, generation, or unexpected application error, when a client calls the affected endpoint, then the response is JSON with the documented error fields and contains no stack trace, SQL statement, credential, secret, or Java class name."
    },
    {
      "id": "AC9",
      "criterion": "Given a successfully created link, when a client resolves it repeatedly using the returned short code, then each resolution uses the same stored destination and existing analytics behavior remains available without altering the redirect target."
    }
  ],
  "decisions": [
    {
      "title": "Treat the repository as brownfield",
      "rationale": "The repository contains implemented controllers, services, persistence abstractions, analytics, documentation, and integration tests rather than only an application template.",
      "alternatives": [
        "Classify as greenfield based only on the presence of the application class"
      ]
    },
    {
      "title": "Use protocol and syntax validation as the default safety boundary",
      "rationale": "The requirement does not identify a reputation or network-access threat model, and blocking private or IP destinations could break legitimate existing users without a defined policy.",
      "alternatives": [
        "Block localhost, private, loopback, link-local, and all IP-literal destinations",
        "Integrate an external malware or reputation service"
      ]
    },
    {
      "title": "Preserve existing API contracts",
      "rationale": "The repository already contains API documentation, controllers, response types, and integration tests; changing routes or response shapes would create unnecessary compatibility risk.",
      "alternatives": [
        "Introduce a new versioned API",
        "Redesign the request and response schemas"
      ]
    },
    {
      "title": "Create a distinct code for every successful request",
      "rationale": "Short-code services conventionally represent link instances, and distinct codes make collision and concurrency behavior directly testable without introducing unspecified deduplication semantics.",
      "alternatives": [
        "Return the existing code for the same destination",
        "Make idempotency configurable"
      ]
    },
    {
      "title": "Use bounded collision retries",
      "rationale": "Retrying handles normal random collisions, while a bound prevents an exhausted or faulty generator from hanging requests indefinitely.",
      "alternatives": [
        "Retry indefinitely",
        "Fail on the first collision"
      ]
    },
    {
      "title": "Preserve accepted destination URLs",
      "rationale": "Silent normalization can change query parameters, fragments, paths, or user-visible redirect behavior; validation is required, but rewriting is not implied.",
      "alternatives": [
        "Canonicalize URLs before persistence",
        "Normalize only host and scheme casing"
      ]
    }
  ]
}

{
  "summary": "Harden short-link creation and redirection by using a configured public origin, rejecting self-origin destinations after canonical host comparison, limiting link creation, and enforcing configurable link expiration while preserving existing behavior.",
  "changeType": "brownfield",
  "functional": [
    "Use the existing configured public-origin resolution (app.public-origin and existing server-configuration fallback behavior) to construct the shortUrl returned by the link-creation API.",
    "Use that same configured public origin, never the incoming request Host header, when constructing the link-creation response Location header.",
    "During destination URL validation, canonicalize hostnames before the self-origin comparison by lowercasing, removing a trailing dot, and converting internationalized hostnames to their ASCII IDN/punycode form. Equivalent host representations must be treated as the same host and rejected as self-origin destinations.",
    "Apply a limit of 30 link-creation requests per minute per client IP. A request beyond the limit must return HTTP 429 using the existing standard error-response body.",
    "Allow link creation requests to include an optional expiresInDays value. Accept integer values from 1 through 365 inclusive.",
    "When expiresInDays is omitted, set the link expiration to 90 days after creation.",
    "Persist the expiration time with each link and, when a redirect is requested for an expired link, return HTTP 410 Gone with the existing standard error-response body instead of redirecting.",
    "Continue returning the existing validation error response for expiresInDays values outside 1 through 365 or values that are not valid integers.",
    "Preserve existing link creation, redirect, analytics, and error behavior unless explicitly changed above, including returning HTTP 503 when short-code generation is exhausted.",
    "Do not add malicious-URL scanning and do not reject destinations solely because they resolve to private networks."
  ],
  "nonFunctional": [
    "The public-origin rule must be deterministic and must not be bypassable by supplying a forged request Host header.",
    "Rate limiting must be applied independently for each client IP and must not allow one client's requests to consume another client's quota.",
    "Expiration checks must be enforced on every redirect request, including links created before the new expiration behavior if such records exist.",
    "The new error responses must remain compatible with the application's existing standard error body format."
  ],
  "outOfScope": [
    "Malicious-URL reputation or content scanning.",
    "Blocking loopback, private, link-local, or other non-public destination networks.",
    "Changing short-code generation, collision handling, or the existing HTTP 503 behavior for code-generation exhaustion.",
    "Changing analytics semantics except that an expired link must not be redirected or counted as a successful redirect.",
    "Adding user authentication, per-account quotas, or administrative rate-limit controls.",
    "Changing the configured public-origin precedence or introducing a new origin configuration mechanism."
  ],
  "openQuestions": [
    {
      "question": "Which request attribute identifies the client IP for rate limiting when the service is behind a proxy or load balancer?",
      "assumption": "Use the application's existing client-IP resolution behavior; otherwise use the direct remote address and do not trust arbitrary forwarding headers.",
      "answer": "Human scope decision requires rate limiting per client IP; no alternative proxy-trust policy was specified."
    },
    {
      "question": "Should the one-minute rate limit use a fixed window, sliding window, or token bucket?",
      "assumption": "Use a rolling one-minute window with at most 30 accepted link-creation requests per client IP.",
      "answer": ""
    },
    {
      "question": "How should expiration be calculated around time zones and boundary instants?",
      "assumption": "Calculate expiration as the creation instant plus the requested number of 24-hour days using UTC timestamps; a link is expired when the current instant is at or after its expiration instant.",
      "answer": ""
    },
    {
      "question": "How should rate-limit state behave across multiple application instances?",
      "assumption": "Enforce the limit using the application's available shared infrastructure if one already exists; otherwise enforce it within the running service instance without adding a new external dependency.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given a valid link-creation request to the existing link-creation endpoint, when the request Host header differs from the configured public origin, then the successful response shortUrl uses the configured public origin and does not contain the request Host value."
    },
    {
      "id": "AC2",
      "criterion": "Given a valid link-creation request, when the link is created successfully, then the response Location header uses the configured public origin and does not contain the request Host value."
    },
    {
      "id": "AC3",
      "criterion": "Given a destination whose host is equivalent to the configured public-origin host after case normalization, trailing-dot removal, or IDN/punycode normalization, when link creation is attempted, then the API rejects it using the existing invalid-URL error behavior and does not create a link."
    },
    {
      "id": "AC4",
      "criterion": "Given 30 link-creation requests from the same client IP within a rolling 60-second interval, when a 31st request from that IP is submitted within the interval, then the API returns HTTP 429 and the response conforms to the existing standard error-body schema."
    },
    {
      "id": "AC5",
      "criterion": "Given requests from two different client IPs, when each IP submits requests within its own 30-per-minute allowance, then one IP's requests do not cause the other IP's requests to receive HTTP 429."
    },
    {
      "id": "AC6",
      "criterion": "Given a link-creation request with no expiresInDays field, when creation succeeds, then the persisted link expires 90 days after its creation instant and remains redirectable before that expiration."
    },
    {
      "id": "AC7",
      "criterion": "Given a link-creation request with expiresInDays equal to each boundary value 1 and 365, when creation succeeds, then the link is created with an expiration respectively 1 or 365 days after creation."
    },
    {
      "id": "AC8",
      "criterion": "Given a link-creation request with expiresInDays less than 1, greater than 365, non-integer, or otherwise invalid, when creation is attempted, then the API returns the existing validation-error status and standard error body and does not create the link."
    },
    {
      "id": "AC9",
      "criterion": "Given a link whose expiration instant has passed or has been reached, when its short-code endpoint is requested, then the API returns HTTP 410 Gone with the existing standard error body, does not redirect, and does not record a successful redirect click."
    },
    {
      "id": "AC10",
      "criterion": "Given a non-expired link, when its short-code endpoint is requested, then existing redirect behavior is preserved and the response redirects to the stored destination."
    },
    {
      "id": "AC11",
      "criterion": "Given a valid link-creation request when short-code generation is exhausted, then the API continues to return HTTP 503 with the existing error behavior."
    },
    {
      "id": "AC12",
      "criterion": "Given a destination URL that is not self-origin and is otherwise accepted by the existing validator, when it targets a private or local network, then this change does not reject it solely for that network classification."
    }
  ],
  "decisions": [
    {
      "title": "Classify the work as brownfield",
      "rationale": "The repository contains an implemented shortener, controllers, services, persistence classes, configuration, and integration tests rather than only a template application.",
      "alternatives": [
        "greenfield"
      ]
    },
    {
      "title": "Use the configured public origin for generated links",
      "rationale": "This prevents Host-header manipulation from changing externally advertised URLs and follows the explicit human scope decision.",
      "alternatives": [
        "derive the origin from the incoming request",
        "allow the request Host header to override configuration"
      ]
    },
    {
      "title": "Canonicalize hostnames before self-origin comparison",
      "rationale": "Case differences, trailing dots, and Unicode versus punycode forms can otherwise bypass a logically equivalent-host check.",
      "alternatives": [
        "compare raw host strings",
        "compare only lowercased host strings"
      ]
    },
    {
      "title": "Use a rolling 60-second rate-limit window",
      "rationale": "A rolling window provides a predictable interpretation of 30 requests per minute and avoids an excessive boundary burst inherent in fixed wall-clock windows.",
      "alternatives": [
        "fixed calendar-minute window",
        "token bucket"
      ]
    },
    {
      "title": "Default expiration to 90 days and permit 1 through 365 days",
      "rationale": "These values are explicitly defined by the human scope decision; UTC instants and 24-hour increments make enforcement deterministic.",
      "alternatives": [
        "no default expiration",
        "calendar-day expiration in the server's local time zone"
      ]
    },
    {
      "title": "Return 410 Gone for expired redirects",
      "rationale": "HTTP 410 explicitly communicates that the resource is intentionally no longer available and is required by the scope decision.",
      "alternatives": [
        "404 Not Found",
        "redirect to an error page"
      ]
    },
    {
      "title": "Preserve the existing standard error body",
      "rationale": "The requirement explicitly calls for the standard body for rate-limit and expiration errors and preserving existing API compatibility reduces unrelated client impact.",
      "alternatives": [
        "introduce separate response schemas for 429 and 410"
      ]
    },
    {
      "title": "Exclude URL threat scanning and private-network blocking",
      "rationale": "The human scope decision explicitly rejects both protections for this change.",
      "alternatives": [
        "scan destinations for malicious content",
        "reject private or local network destinations"
      ]
    }
  ]
}

{
  "impactedFiles": [
    {
      "path": "src/main/java/com/example/shortener/Link.java",
      "changeKind": "modify",
      "reason": "Add a nullable expiration timestamp to persisted links, with accessors and constructor support for newly created links."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkCreateRequest.java",
      "changeKind": "modify",
      "reason": "Add optional expiresInDays input with validation requiring integer values from 1 through 365 when provided."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkService.java",
      "changeKind": "modify",
      "reason": "Calculate expiration using the injected UTC clock, default omitted values to 90 days, persist expiration, and reject expired links before recording analytics or incrementing click counts while preserving code-generation exhaustion behavior."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkController.java",
      "changeKind": "modify",
      "reason": "Use PublicOriginProvider rather than request Host-derived values for the creation response shortUrl and Location header, pass expiresInDays to the service, and apply per-instance creation rate limiting using request.getRemoteAddr()."
    },
    {
      "path": "src/main/java/com/example/shortener/PublicOriginProvider.java",
      "changeKind": "modify",
      "reason": "Expose the configured or existing fallback public origin for response URL construction and canonicalize comparison hostnames using lowercase, trailing-dot removal, and IDN ASCII conversion."
    },
    {
      "path": "src/main/java/com/example/shortener/UrlValidator.java",
      "changeKind": "modify",
      "reason": "Use the strengthened PublicOriginProvider self-origin comparison so equivalent case, trailing-dot, and IDN/punycode host representations are rejected."
    },
    {
      "path": "src/main/java/com/example/shortener/RedirectController.java",
      "changeKind": "modify",
      "reason": "Allow the expiration exception from link following to be translated through the existing standard error response handling while preserving normal 302 redirects."
    },
    {
      "path": "src/main/java/com/example/shortener/GlobalExceptionHandler.java",
      "changeKind": "modify",
      "reason": "Add standard ProblemDetail responses for rate-limit exhaustion with HTTP 429 and expired links with HTTP 410."
    },
    {
      "path": "src/main/java/com/example/shortener/RateLimitExceededException.java",
      "changeKind": "create",
      "reason": "Represent a creation request rejected after the client IP's rolling 30-request-per-60-second allowance is exhausted."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkExpiredException.java",
      "changeKind": "create",
      "reason": "Represent an expired link redirect attempt so it can return the standard HTTP 410 error body."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkCreationRateLimiter.java",
      "changeKind": "create",
      "reason": "Maintain an independent rolling one-minute request window for each remote client IP within the application instance."
    },
    {
      "path": "src/test/java/com/example/shortener/UrlValidatorTest.java",
      "changeKind": "modify",
      "reason": "Cover self-origin rejection for case-normalized, trailing-dot, and IDN/punycode-equivalent hosts while retaining acceptance of unrelated and private-network destinations."
    },
    {
      "path": "src/test/java/com/example/shortener/PublicOriginValidationIntegrationTest.java",
      "changeKind": "modify",
      "reason": "Add integration coverage proving equivalent canonical host forms are rejected and request Host cannot alter configured-origin behavior."
    },
    {
      "path": "src/test/java/com/example/shortener/FallbackPublicOriginValidationIntegrationTest.java",
      "changeKind": "modify",
      "reason": "Verify the fallback public origin is used for self-origin validation and response construction independently of a forged Host header."
    },
    {
      "path": "src/test/java/com/example/shortener/UrlShortenerIntegrationTest.java",
      "changeKind": "modify",
      "reason": "Assert creation shortUrl and Location use the configured/fallback public origin rather than the incoming Host, and add expiration, validation, rate-limit, and expired-redirect behavior coverage."
    },
    {
      "path": "src/test/java/com/example/shortener/AnalyticsIntegrationTest.java",
      "changeKind": "modify",
      "reason": "Add coverage that expired redirects do not create click events or successful redirect counts."
    },
    {
      "path": "src/test/java/com/example/shortener/LinkServiceUnitTest.java",
      "changeKind": "modify",
      "reason": "Test default and explicit expiration calculation using a fixed clock."
    },
    {
      "path": "src/test/java/com/example/shortener/LinkServiceContractTest.java",
      "changeKind": "modify",
      "reason": "Preserve and extend service contract tests for expired-link rejection, no click increment on expiration, and unchanged 503 code-generation exhaustion."
    },
    {
      "path": "src/test/java/com/example/shortener/LinkCreationRateLimiterTest.java",
      "changeKind": "create",
      "reason": "Unit-test the 30-request rolling-window boundary, rejection of the 31st request, independent quotas for different remote IPs, and window expiry."
    },
    {
      "path": "src/test/java/com/example/shortener/LinkCreateRequestValidationTest.java",
      "changeKind": "create",
      "reason": "Test omitted expiration, boundary values 1 and 365, values outside the range, fractional values, and malformed non-integer input."
    },
    {
      "path": "src/test/java/com/example/shortener/PublicOriginProviderTest.java",
      "changeKind": "create",
      "reason": "Test configured-origin and server-configuration fallback resolution plus canonical host matching."
    }
  ],
  "impactedApis": [
    {
      "endpoint": "POST /api/links",
      "change": "The optional expiresInDays request field is accepted and validated; omitted values create links expiring 90 days after creation, while values 1 through 365 set the corresponding UTC 24-hour expiration. Successful shortUrl and Location values use the configured public origin or existing server fallback, never the request Host. Requests beyond 30 per rolling 60 seconds per remote IP return HTTP 429 with the existing ProblemDetail body.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /{code}",
      "change": "Expired newly created links return HTTP 410 Gone with the existing standard error body and do not redirect or record a successful click. Non-expired links retain the existing 302 behavior.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /api/links/{code}",
      "change": "No contract change is required for link details; existing behavior remains available. Creation-specific shortUrl and Location construction is hardened.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /api/links/{code}/analytics",
      "change": "No direct contract change; analytics for expired links remain readable, while redirects after expiration are not counted.",
      "backwardCompatible": true
    }
  ],
  "dataChanges": [
    "Add a nullable expiration timestamp column to the links table, stored as a UTC instant and indexed only if query performance later requires it.",
    "New links persist expiration at creation time, defaulting to creation instant plus 90 days.",
    "Existing rows with a null expiration remain non-expiring and continue to redirect, per the binding human decision; no backfill migration is required.",
    "The current Hibernate ddl-auto=update configuration can add the nullable column in the existing deployment model, but a production migration should be supplied if schema changes are managed outside Hibernate."
  ],
  "testsToUpdate": [
    "Update UrlValidatorTest for canonical host comparison and private-network non-blocking behavior.",
    "Update PublicOriginValidationIntegrationTest and FallbackPublicOriginValidationIntegrationTest for configured/fallback-origin response and validation behavior.",
    "Update UrlShortenerIntegrationTest for Host-independent creation URLs, expiresInDays validation, default and boundary expiration, 429 responses, and 410 redirects.",
    "Update AnalyticsIntegrationTest to verify expired redirects do not produce analytics events.",
    "Update LinkServiceUnitTest and LinkServiceContractTest for clock-based expiration and expired-link contracts.",
    "Add LinkCreationRateLimiterTest for rolling-window and per-remote-IP isolation.",
    "Add LinkCreateRequestValidationTest for all expiresInDays validation cases.",
    "Add PublicOriginProviderTest for fallback resolution and IDN/trailing-dot/case canonicalization."
  ],
  "risks": [
    "The in-memory rate limiter is scoped to one application instance, so multiple instances can each admit up to 30 requests per IP; this is an explicitly accepted deployment limitation.",
    "Rate limiting uses request.getRemoteAddr() and does not trust X-Forwarded-For, so clients behind a proxy may be grouped under the proxy address; this is an explicitly binding decision.",
    "Existing links with null expiration never expire, so expiration enforcement is not retroactively applied to pre-change records.",
    "Concurrent requests from the same IP require atomic limiter state updates; an incorrect implementation could admit more than 30 requests.",
    "Adding a non-null expiration to newly persisted entities without preserving nullable handling could break reads of legacy rows.",
    "Changing response URL construction could expose configuration errors or produce unexpected URLs if app.public-origin contains a path, since the configured value is intended to be an origin.",
    "IDN canonicalization may reject destinations that are semantically self-origin even when their textual representation differs, which is intentional.",
    "The rate limiter may affect integration tests that create many links from the same MockMvc remote address unless tests isolate limiter state or use distinct remote addresses."
  ],
  "decisions": [
    {
      "title": "Use the configured PublicOriginProvider for creation URLs",
      "rationale": "The requirement forbids deriving creation shortUrl and Location from the incoming Host header and requires preserving the existing app.public-origin/server fallback precedence.",
      "alternatives": [
        "Continue constructing URLs from HttpServletRequest scheme, server name, and port",
        "Introduce a second origin configuration mechanism"
      ]
    },
    {
      "title": "Canonicalize hosts with IDN.toASCII after lowercase and trailing-dot removal",
      "rationale": "This treats equivalent DNS representations as the same host while retaining the existing scheme and effective-port comparison.",
      "alternatives": [
        "Compare raw URI host strings",
        "Use only lowercase comparison",
        "Reject all non-ASCII hostnames"
      ]
    },
    {
      "title": "Implement rate limiting in an application-scoped in-memory component",
      "rationale": "The binding decision specifies a rolling one-minute limit per remote address and explicitly accepts per-application-instance state without adding an external dependency.",
      "alternatives": [
        "Use a fixed one-minute window",
        "Add Redis or another shared rate-limit store",
        "Trust X-Forwarded-For for proxy-aware identity"
      ]
    },
    {
      "title": "Use request.getRemoteAddr() as the client identity",
      "rationale": "The human binding clarification explicitly rejects trusting arbitrary forwarding headers in this change.",
      "alternatives": [
        "Use the first X-Forwarded-For address",
        "Use a configurable proxy trust chain"
      ]
    },
    {
      "title": "Represent expiration as a nullable UTC Instant",
      "rationale": "Instant matches the existing Clock-based UTC behavior and nullable storage allows pre-change links to remain non-expiring as required.",
      "alternatives": [
        "Backfill all existing links with 90-day expiration",
