    {
      "title": "Use the resolved public origin for creation URLs",
      "rationale": "The configured origin is deterministic and cannot be changed by a forged request Host header. The existing configured-origin precedence and fallback behavior are preserved.",
      "alternatives": [
        "Build URLs from request scheme, server name, port, and Host header; rejected because those values can be client-controlled or proxy-dependent.",
        "Introduce a new origin configuration property; rejected because changing origin configuration precedence is out of scope."
      ]
    },
    {
      "title": "Canonicalize self-origin hosts with IDN ASCII conversion",
      "rationale": "Lowercase, trailing-dot removal, and IDN/punycode normalization ensure equivalent host representations cannot bypass the self-origin check.",
      "alternatives": [
        "Compare raw host strings; rejected because case, trailing dots, and Unicode/punycode variants would differ textually.",
        "Resolve hostnames through DNS; rejected because it adds latency, environmental dependence, and is unnecessary for the specified equivalence."
      ]
    },
    {
      "title": "Use a rolling 60-second in-process limiter keyed by remote address",
      "rationale": "This implements the required 30-per-minute rolling window, isolates quotas by client IP, and follows the binding decision not to trust forwarding headers or add infrastructure.",
      "alternatives": [
        "Fixed one-minute windows; rejected because requests could be clustered at window boundaries.",
        "Token bucket; rejected because the requirement specifies a rolling window and exact 30-request boundary behavior.",
        "Redis or database-backed state; rejected because external infrastructure is out of scope."
      ]
    },
