      "title": "Represent optional expiration as nullable Integer and persisted Instant",
      "rationale": "Nullable Integer permits omission while Bean Validation enforces 1..365 when supplied. Instant gives unambiguous UTC boundary comparisons and fits the existing clock-based service design.",
      "alternatives": [
        "Primitive int; rejected because omission would be indistinguishable from an invalid default.",
        "Persist a local date; rejected because expiration is defined as creation instant plus 24-hour UTC days.",
        "Persist a non-null expiration for all rows through backfill; rejected because legacy null-expiration links must remain non-expiring."
      ]
    },
    {
      "title": "Treat expiration equality as expired before analytics",
      "rationale": "The requirement explicitly defines links as expired at or after the expiration instant and requires expired redirects not to count as successful clicks.",
      "alternatives": [
        "Check expiration after recording analytics; rejected because expired requests would incorrectly increment click metrics.",
        "Use a strict-after comparison; rejected because a request exactly at the expiration instant must return 410."
      ]
    },
