{"files":[{"path":"src/main/java/com/example/shortener/Link.java","content":"package com.example.shortener;

import java.time.Instant;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "links")
public class Link {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "original_url", nullable = false, length = 2048)
    private String url;

    @Column(name = "short_code", nullable = false, unique = true, length = 7)
    private String code;

    @Column(name = "click_count", nullable = false)
    private long clickCount;

    @Column(name = "expires_at")
    private Instant expiresAt;

    protected Link() {
    }

    public Link(String url, String code) {
        this(url, code, null);
    }

    public Link(String url, String code, Instant expiresAt) {
        this.url = url;
        this.code = code;
        this.clickCount = 0;
        this.expiresAt = expiresAt;
    }

    public Long getId() {
        return id;
    }

    public String getUrl() {
        return url;
    }

    public String getCode() {
        return code;
    }

    public long getClickCount() {
        return clickCount;
    }

    public Instant getExpiresAt() {
        return expiresAt;
    }
}
