"},{"path":"src/main/java/com/example/shortener/LinkCreationRateLimiter.java","content":"package com.example.shortener;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.stereotype.Component;

@Component
public class LinkCreationRateLimiter {

    private static final int MAX_REQUESTS = 30;
    private static final Duration WINDOW = Duration.ofMinutes(1);

    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();
    private final Clock clock;

    public LinkCreationRateLimiter(Clock clock) {
        this.clock = clock;
    }

    public LinkCreationRateLimiter() {
        this(Clock.systemUTC());
    }

    public void admit(String clientIp) {
        String key = clientIp == null ? "" : clientIp;
        Bucket bucket = buckets.computeIfAbsent(key, ignored -> new Bucket());
        Instant now = Instant.now(clock);
        synchronized (bucket) {
            Instant cutoff = now.minus(WINDOW);
            while (!bucket.timestamps.isEmpty()
                    && bucket.timestamps.peekFirst().isBefore(cutoff)) {
                bucket.timestamps.removeFirst();
            }
            if (bucket.timestamps.size() >= MAX_REQUESTS) {
                throw new RateLimitExceededException();
            }
            bucket.timestamps.addLast(now);
        }
        if (bucket.timestamps.isEmpty()) {
            buckets.remove(key, bucket);
        }
    }

    private static final class Bucket {
        private final Deque<Instant> timestamps = new ArrayDeque<>();
    }
}
"},{"path":"src/main/java/com/example/shortener/PublicOriginProvider.java","content":"package com.example.shortener;

import java.net.IDN;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class PublicOriginProvider {

    private final String scheme;
    private final String hostname;
    private final int port;
    private final String origin;

    @Autowired
    public PublicOriginProvider(@Value("${app.public-origin:}") String configuredOrigin,
                                @Value("${server.address:localhost}") String serverAddress,
                                @Value("${server.port:8080}") int serverPort,
                                @Value("${server.ssl.enabled:false}") boolean sslEnabled) {
        String fallbackScheme = sslEnabled ? "https" : "http";
        String fallbackHost = serverAddress == null || serverAddress.isBlank() ? "localhost" : serverAddress;
        String value = configuredOrigin == null || configuredOrigin.isBlank()
                ? fallbackScheme + "://" + fallbackHost + ":" + serverPort : configuredOrigin;
        try {
            URI uri = new URI(value);
            String parsedScheme = uri.getScheme();
            String parsedHost = hostOf(uri);
            if (parsedScheme == null || parsedHost == null
                    || !(parsedScheme.equalsIgnoreCase("http") || parsedScheme.equalsIgnoreCase("https"))
                    || uri.getRawUserInfo() != null || uri.getRawQuery() != null
                    || uri.getRawFragment() != null || (uri.getRawPath() != null && !uri.getRawPath().isEmpty()
                    && !uri.getRawPath().equals("/"))) {
                throw new IllegalArgumentException();
            }
            this.scheme = parsedScheme.toLowerCase(Locale.ROOT);
            this.hostname = canonicalHost(parsedHost);
            this.port = effectivePort(this.scheme, uri.getPort());
            this.origin = this.scheme + "://" + formatHost(parsedHost) + portSuffix(this.scheme, uri.getPort());
        } catch (URISyntaxException | IllegalArgumentException exception) {
            throw new IllegalStateException("Invalid public origin configuration", exception);
        }
    }

    public PublicOriginProvider() {
        this("http://localhost:8080", "localhost", 8080, false);
    }

    public String origin() {
        return origin;
    }

    public String shortUrl(String code) {
        return origin + "/" + code;
    }

    public boolean matches(URI uri) {
        if (uri == null || uri.getScheme() == null) {
            return false;
        }
        String host = hostOf(uri);
        if (host == null) {
            return false;
        }
        try {
            return scheme.equalsIgnoreCase(uri.getScheme())
                    && hostname.equals(canonicalHost(host))
                    && port == effectivePort(uri.getScheme(), uri.getPort());
        } catch (IllegalArgumentException exception) {
            return false;
        }
    }

    static String canonicalHost(String host) {
        String value = host.toLowerCase(Locale.ROOT);
        while (value.endsWith(".") && value.length() > 0) {
            value = value.substring(0, value.length() - 1);
        }
        if (value.isEmpty()) {
            throw new IllegalArgumentException("Invalid hostname");
        }
        return IDN.toASCII(value, IDN.USE_STD3_ASCII_RULES).toLowerCase(Locale.ROOT);
    }

    private static String hostOf(URI uri) {
        if (uri.getHost() != null) {
            return uri.getHost();
        }
        String authority = uri.getRawAuthority();
        if (authority == null || authority.contains("@")) {
            return null;
        }
        if (authority.startsWith("[")) {
            int end = authority.indexOf(']');
            return end > 0 ? authority.substring(1, end) : null;
        }
        int colon = authority.lastIndexOf(':');
        return colon >= 0 && authority.indexOf(':') == colon
                ? authority.substring(0, colon) : authority;
    }

    private static String formatHost(String host) {
        String canonical = canonicalHost(host);
        return canonical.contains(":") ? "[" + canonical + "]" : canonical;
    }

    private static String portSuffix(String scheme, int explicitPort) {
        int effective = effectivePort(scheme, explicitPort);
        return effective == ("https".equalsIgnoreCase(scheme) ? 443 : 80) ? "" : ":" + effective;
    }

    private static int effectivePort(String scheme, int explicitPort) {
        return explicitPort >= 0 ? explicitPort : ("https".equalsIgnoreCase(scheme) ? 443 : 80);
    }
}
"},{"path":"src/main/java/com/example/shortener/UrlValidator.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {

    private final PublicOriginProvider publicOriginProvider;

    @Autowired
    public UrlValidator(PublicOriginProvider publicOriginProvider) {
        this.publicOriginProvider = publicOriginProvider;
    }

    public UrlValidator() {
        this.publicOriginProvider = new PublicOriginProvider();
    }

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            throw new InvalidUrlException("url is required and must not be blank");
        }
        if (value.length() > 2048) {
            throw new InvalidUrlException("url must not exceed 2048 characters");
        }
        try {
            URI uri = new URI(value);
            String scheme = uri.getScheme();
            if (!uri.isAbsolute() || scheme == null
                    || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                    || uri.getRawAuthority() == null) {
                throw new InvalidUrlException("url must be an absolute HTTP or HTTPS URL");
            }
            if (publicOriginProvider.matches(uri)) {
                throw new InvalidUrlException("url must not point to the shortener itself");
            }
        } catch (URISyntaxException exception) {
            throw new InvalidUrlException("url must be a valid absolute HTTP or HTTPS URL");
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkService.java","content":"package com.example.shortener;

import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Optional;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkService {

    private static final int MAX_CREATE_ATTEMPTS = 10;
    private static final int MAX_REFERRER_LENGTH = 2048;
    private static final int DEFAULT_EXPIRATION_DAYS = 90;

    private final LinkRepository repository;
    private final ShortCodeGenerator codeGenerator;
    private final ClickEventRepository clickEventRepository;
    private final Clock clock;

    @Autowired
    public LinkService(LinkRepository repository, ShortCodeGenerator codeGenerator,
                       ClickEventRepository clickEventRepository, Clock clock) {
        this.repository = repository;
        this.codeGenerator = codeGenerator;
        this.clickEventRepository = clickEventRepository;
        this.clock = clock;
    }

    public LinkService(LinkRepository repository, ShortCodeGenerator codeGenerator,
                       ClickEventRepository clickEventRepository) {
        this(repository, codeGenerator, clickEventRepository, Clock.systemUTC());
    }

    public LinkService(LinkRepository repository, ShortCodeGenerator codeGenerator) {
        this(repository, codeGenerator, null, Clock.systemUTC());
    }

    public Link create(String url) {
        return create(url, null);
    }

    public Link create(String url, Integer expiresInDays) {
        int days = expiresInDays == null ? DEFAULT_EXPIRATION_DAYS : expiresInDays;
        Instant createdAt = Instant.now(clock);
        Instant expiresAt = createdAt.plus((long) days, ChronoUnit.DAYS);
        for (int attempt = 0; attempt < MAX_CREATE_ATTEMPTS; attempt++) {
            String code = codeGenerator.generate();
            if (repository.existsByCode(code)) {
                continue;
            }
            try {
                return repository.saveAndFlush(new Link(url, code, expiresAt));
            } catch (DataIntegrityViolationException exception) {
                // A concurrent insert may have won the unique-code race; try a new code.
            }
        }
        throw new CodeGenerationException();
    }

    public Link getByCode(String code) {
        return repository.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
    }

    @Transactional
    public String follow(String code, String referer) {
        Optional<Link> found = repository.findByCode(code);
        if (found.isEmpty()) {
            throw new LinkNotFoundException(code);
        }
        Link link = found.get();
        if (link.getExpiresAt() != null && !Instant.now(clock).isBefore(link.getExpiresAt())) {
            throw new LinkExpiredException(code);
        }
        if (clickEventRepository == null) {
            repository.incrementClickCount(code);
            return link.getUrl();
        }
        clickEventRepository.save(new ClickEvent(link, Instant.now(clock), normalizeReferer(referer)));
        repository.incrementClickCount(code);
        return link.getUrl();
    }

    public String follow(String code) {
        return follow(code, null);
    }

    private String normalizeReferer(String referer) {
        if (referer == null || referer.isEmpty()) {
            return null;
        }
        return referer.length() <= MAX_REFERRER_LENGTH ? referer : referer.substring(0, MAX_REFERRER_LENGTH);
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkController.java","content":"package com.example.shortener;

import java.net.URI;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/links")
public class LinkController {

    private final LinkService linkService;
    private final UrlValidator urlValidator;
    private final AnalyticsService analyticsService;
    private final PublicOriginProvider publicOriginProvider;
    private final LinkCreationRateLimiter rateLimiter;

    @Autowired
    public LinkController(LinkService linkService, UrlValidator urlValidator,
                          AnalyticsService analyticsService, PublicOriginProvider publicOriginProvider,
                          LinkCreationRateLimiter rateLimiter) {
        this.linkService = linkService;
        this.urlValidator = urlValidator;
        this.analyticsService = analyticsService;
        this.publicOriginProvider = publicOriginProvider;
        this.rateLimiter = rateLimiter;
    }

    public LinkController(LinkService linkService, UrlValidator urlValidator) {
        this(linkService, urlValidator, null, new PublicOriginProvider(), new LinkCreationRateLimiter());
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody LinkCreateRequest request,
                                                HttpServletRequest httpRequest) {
        rateLimiter.admit(httpRequest.getRemoteAddr());
        urlValidator.validate(request.url());
        Link link = linkService.create(request.url(), request.expiresInDays());
        String shortUrl = publicOriginProvider.shortUrl(link.getCode());
        return ResponseEntity.created(URI.create(shortUrl)).body(LinkResponse.from(link, shortUrl));
    }

    @GetMapping("/{code}/analytics")
    public AnalyticsResponse analytics(@PathVariable String code) {
        return analyticsService.getAnalytics(code);
    }

    @GetMapping("/{code}")
    public LinkResponse details(@PathVariable String code, HttpServletRequest httpRequest) {
        Link link = linkService.getByCode(code);
        return LinkResponse.from(link, buildRequestShortUrl(httpRequest, link.getCode()));
    }

    private String buildRequestShortUrl(HttpServletRequest request, String code) {
        StringBuilder result = new StringBuilder().append(request.getScheme()).append("://")
                .append(request.getServerName());
        int port = request.getServerPort();
        boolean defaultPort = ("http".equalsIgnoreCase(request.getScheme()) && port == 80)
                || ("https".equalsIgnoreCase(request.getScheme()) && port == 443);
        if (!defaultPort) {
            result.append(':').append(port);
        }
        String contextPath = request.getContextPath();
        if (contextPath != null) {
            result.append(contextPath);
        }
        return result.append('/').append(code).toString();
    }
}
"},{"path":"src/main/java/com/example/shortener/GlobalExceptionHandler.java","content":"package com.example.shortener;

import java.net.URI;
import java.util.stream.Collectors;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.http.converter.HttpMessageNotReadableException;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler({InvalidUrlException.class, MethodArgumentNotValidException.class,
            HttpMessageNotReadableException.class})
    public ProblemDetail badRequest(Exception exception, WebRequest request) {
        String detail;
        if (exception instanceof MethodArgumentNotValidException validation) {
            detail = validation.getBindingResult().getFieldErrors().stream()
                    .map(error -> error.getDefaultMessage() == null ? "Invalid request" : error.getDefaultMessage())
                    .collect(Collectors.joining("; "));
        } else if (exception instanceof HttpMessageNotReadableException) {
            detail = "Request body must be valid JSON and include a URL";
        } else {
            detail = exception.getMessage();
        }
        return problem(HttpStatus.BAD_REQUEST, detail, request);
    }

    @ExceptionHandler(LinkNotFoundException.class)
    public ProblemDetail notFound(LinkNotFoundException exception, WebRequest request) {
        return problem(HttpStatus.NOT_FOUND, exception.getMessage(), request);
    }

    @ExceptionHandler(RateLimitExceededException.class)
    public ProblemDetail rateLimited(RateLimitExceededException exception, WebRequest request) {
        return problem(HttpStatus.TOO_MANY_REQUESTS, exception.getMessage(), request);
    }

    @ExceptionHandler(LinkExpiredException.class)
    public ProblemDetail expired(LinkExpiredException exception, WebRequest request) {
        return problem(HttpStatus.GONE, exception.getMessage(), request);
    }

    @ExceptionHandler(CodeGenerationException.class)
    public ProblemDetail unavailable(CodeGenerationException exception, WebRequest request) {
        return problem(HttpStatus.SERVICE_UNAVAILABLE,
                "The service could not generate a unique short code", request);
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail unexpected(Exception exception, WebRequest request) {
        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected server error occurred", request);
    }

    private ProblemDetail problem(HttpStatus status, String detail, WebRequest request) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status,
                detail == null || detail.isBlank() ? status.getReasonPhrase() : detail);
        problem.setTitle(status.getReasonPhrase());
        String description = request.getDescription(false);
        if (description.startsWith("uri=")) {
            problem.setInstance(URI.create(description.substring(4)));
        }
        return problem;
    }
}
