import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.net.URI;

import org.junit.jupiter.api.Test;

class CanonicalPublicOriginTest {

    @Test
    void unicodeAndPunycodeHostsAreEquivalentForSelfOriginValidation() {
        PublicOriginProvider provider = new PublicOriginProvider(
                "https://bücher.example", "localhost", 8080, false);
        UrlValidator validator = new UrlValidator(provider);

        assertThatThrownBy(() -> validator.validate("https://XN--BCHER-KVA.EXAMPLE./target"))
                .isInstanceOf(InvalidUrlException.class);
        assertThatThrownBy(() -> validator.validate("https://bücher.example/target"))
                .isInstanceOf(InvalidUrlException.class);
        org.assertj.core.api.Assertions.assertThat(provider.matches(URI.create("https://xn--bcher-kva.example/")))
                .isTrue();
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkCreationRateLimiterTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.junit.jupiter.api.Test;

class LinkCreationRateLimiterTest {

    @Test
    void admitsThirtyRequestsButRejectsTheThirtyFirstForOneIp() {
        LinkCreationRateLimiter limiter = new LinkCreationRateLimiter(
                Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"), ZoneOffset.UTC));

        for (int i = 0; i < 30; i++) {
            limiter.admit("198.51.100.1");
        }

        assertThatThrownBy(() -> limiter.admit("198.51.100.1"))
                .isInstanceOf(RateLimitExceededException.class);
        limiter.admit("198.51.100.2");
    }

    @Test
    void concurrentAdmissionCannotExceedThirtyRequestsForOneIp() throws Exception {
        LinkCreationRateLimiter limiter = new LinkCreationRateLimiter(Clock.systemUTC());
        int attempts = 100;
        ExecutorService executor = Executors.newFixedThreadPool(10);
        CountDownLatch start = new CountDownLatch(1);
        try {
            List<Future<Boolean>> results = new ArrayList<>();
            for (int i = 0; i < attempts; i++) {
                results.add(executor.submit(() -> {
                    start.await();
                    try {
                        limiter.admit("198.51.100.20");
                        return true;
                    } catch (RateLimitExceededException exception) {
                        return false;
                    }
                }));
            }
            start.countDown();
            long admitted = 0;
            for (Future<Boolean> result : results) {
                if (result.get()) {
                    admitted++;
                }
            }
            assertThat(admitted).isEqualTo(30);
        } finally {
            executor.shutdownNow();
        }
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkServiceExpirationUnitTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class LinkServiceExpirationUnitTest {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator codeGenerator;

    @Mock
    private ClickEventRepository clickEventRepository;

    @Test
    void creationUsesFixedClockAndRequestedExpirationDays() {
        Instant created = Instant.parse("2026-01-01T00:00:00Z");
        when(codeGenerator.generate()).thenReturn("FIXED01");
        when(repository.existsByCode("FIXED01")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Link link = new LinkService(repository, codeGenerator, clickEventRepository,
                Clock.fixed(created, ZoneOffset.UTC)).create("https://example.com/destination", 365);

        assertThat(link.getExpiresAt()).isEqualTo(Instant.parse("2027-01-01T00:00:00Z"));
    }

    @Test
    void expiredAtExactBoundaryDoesNotWriteAnalyticsOrIncrementCount() {
        Instant now = Instant.parse("2026-01-01T00:00:00Z");
        Link link = new Link("https://example.com/expired", "EXPIRED", now);
        when(repository.findByCode("EXPIRED")).thenReturn(Optional.of(link));
        LinkService service = new LinkService(repository, codeGenerator, clickEventRepository,
                Clock.fixed(now, ZoneOffset.UTC));

        assertThatThrownBy(() -> service.follow("EXPIRED", "https://referrer.example"))
                .isInstanceOf(LinkExpiredException.class);

        verify(clickEventRepository, never()).save(any(ClickEvent.class));
        verify(repository, never()).incrementClickCount("EXPIRED");
    }

    @Test
    void nonExpiredLinkRecordsClickAndReturnsDestination() {
        Instant now = Instant.parse("2026-01-01T00:00:00Z");
        Link link = new Link("https://example.com/active", "ACTIVE01", now.plusSeconds(1));
        when(repository.findByCode("ACTIVE01")).thenReturn(Optional.of(link));
        LinkService service = new LinkService(repository, codeGenerator, clickEventRepository,
                Clock.fixed(now, ZoneOffset.UTC));

        assertThat(service.follow("ACTIVE01", "https://referrer.example")).isEqualTo(link.getUrl());
        verify(clickEventRepository).save(any(ClickEvent.class));
        verify(repository).incrementClickCount("ACTIVE01");
    }
}
