{"files":[{"path":"src/main/java/com/example/shortener/LinkCreateRequest.java","content":"package com.example.shortener;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import tools.jackson.databind.JsonNode;

public record LinkCreateRequest(
        @NotBlank(message = "url is required and must not be blank") String url,
        @Min(value = 1, message = "expiresInDays must be between 1 and 365")
        @Max(value = 365, message = "expiresInDays must be between 1 and 365")
        Integer expiresInDays) {

    @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
    public static LinkCreateRequest fromJson(
            @JsonProperty("url") String url,
            @JsonProperty("expiresInDays") JsonNode expiresInDays) {
        return new LinkCreateRequest(url, parseExpiresInDays(expiresInDays));
    }

    private static Integer parseExpiresInDays(JsonNode value) {
        if (value == null || value.isNull()) {
            return null;
        }
        if (!value.isIntegralNumber() || !value.canConvertToInt()) {
            throw new IllegalArgumentException("expiresInDays must be an integer between 1 and 365");
        }
        return value.intValue();
    }
}
