    @ExceptionHandler({InvalidUrlException.class, MethodArgumentNotValidException.class,
            HttpMessageNotReadableException.class})
    public ProblemDetail badRequest(Exception exception, WebRequest request) {
        String detail;
        if (exception instanceof MethodArgumentNotValidException validation) {
            detail = validation.getBindingResult().getFieldErrors().stream()
                    .map(error -> error.getDefaultMessage() == null ? "Invalid request" : error.getDefaultMessage())
                    .collect(Collectors.joining("; "));
        } else if (exception instanceof HttpMessageNotReadableException) {
            detail = "Request body must be valid JSON and include a URL";
        } else {
            detail = exception.getMessage();
        }
        return problem(HttpStatus.BAD_REQUEST, detail, request);
    }

    @ExceptionHandler(LinkNotFoundException.class)
    public ProblemDetail notFound(LinkNotFoundException exception, WebRequest request) {
        return problem(HttpStatus.NOT_FOUND, exception.getMessage(), request);
    }

    @ExceptionHandler(RateLimitExceededException.class)
    public ProblemDetail rateLimited(RateLimitExceededException exception, WebRequest request) {
        return problem(HttpStatus.TOO_MANY_REQUESTS, exception.getMessage(), request);
    }

    @ExceptionHandler(LinkExpiredException.class)
    public ProblemDetail expired(LinkExpiredException exception, WebRequest request) {
        return problem(HttpStatus.GONE, exception.getMessage(), request);
    }

    @ExceptionHandler(CodeGenerationException.class)
    public ProblemDetail unavailable(CodeGenerationException exception, WebRequest request) {
        return problem(HttpStatus.SERVICE_UNAVAILABLE,
                "The service could not generate a unique short code", request);
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail unexpected(Exception exception, WebRequest request) {
        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected server error occurred", request);
    }

    private ProblemDetail problem(HttpStatus status, String detail, WebRequest request) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status,
                detail == null || detail.isBlank() ? status.getReasonPhrase() : detail);
        problem.setTitle(status.getReasonPhrase());
        String description = request.getDescription(false);
        if (description.startsWith("uri=")) {
            problem.setInstance(URI.create(description.substring(4)));
        }
        return problem;
    }
}
