{"files":[{"path":"src/test/java/com/example/shortener/StrictExpirationJsonIntegrationTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.RequestPostProcessor;

@SpringBootTest
@AutoConfigureMockMvc
class StrictExpirationJsonIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private LinkRepository linkRepository;

    @Test
    void fractionalAndStringExpirationValuesAreRejectedWithoutCreatingLinks() throws Exception {
        String fractionalUrl = "https://example.com/strict-fractional-" + System.nanoTime();
        String stringUrl = "https://example.com/strict-string-" + System.nanoTime();

        mockMvc.perform(post("/api/links")
                        .with(remoteAddress("198.51.100.201"))
                        .contentType("application/json")
                        .content("{\"url\":\"" + fractionalUrl + "\",\"expiresInDays\":1.5}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.title").value("Bad Request"))
                .andExpect(jsonPath("$.status").value(400))
                .andExpect(jsonPath("$.detail").isNotEmpty())
                .andExpect(jsonPath("$.instance").exists());

        mockMvc.perform(post("/api/links")
                        .with(remoteAddress("198.51.100.202"))
                        .contentType("application/json")
                        .content("{\"url\":\"" + stringUrl + "\",\"expiresInDays\":\"1\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.title").value("Bad Request"))
                .andExpect(jsonPath("$.status").value(400))
                .andExpect(jsonPath("$.detail").isNotEmpty())
                .andExpect(jsonPath("$.instance").exists());

        assertThat(linkRepository.findAll())
                .noneMatch(link -> fractionalUrl.equals(link.getUrl()) || stringUrl.equals(link.getUrl()));
    }

    private RequestPostProcessor remoteAddress(String address) {
        return request -> {
            request.setRemoteAddr(address);
            return request;
        };
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkHardeningIntegrationTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.Duration;
import java.time.Instant;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.request.RequestPostProcessor;

import com.jayway.jsonpath.JsonPath;

@SpringBootTest(properties = "app.public-origin=https://public.shortener.example")
@AutoConfigureMockMvc
class LinkHardeningIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private LinkRepository linkRepository;

    @Autowired
    private ClickEventRepository clickEventRepository;

    @Test
    void creationUsesConfiguredOriginForShortUrlAndLocationDespiteForgedHost() throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .with(remoteAddress("192.0.2.101"))
                        .header("Host", "attacker.example")
                        .contentType("application/json")
                        .content("{\"url\":\"https://destination.example/origin-test\"}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", org.hamcrest.Matchers.startsWith("https://public.shortener.example/")))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.startsWith("https://public.shortener.example/")))
                .andReturn();

        String response = result.getResponse().getContentAsString();
        assertThat(response).doesNotContain("attacker.example");
        assertThat(result.getResponse().getHeader("Location")).doesNotContain("attacker.example");
    }

    @Test
    void equivalentCaseAndTrailingDotSelfOriginHostsAreRejected() throws Exception {
        mockMvc.perform(post("/api/links")
                        .with(remoteAddress("192.0.2.102"))
                        .contentType("application/json")
                        .content("{\"url\":\"https://PUBLIC.SHORTENER.EXAMPLE./target\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.title").value("Bad Request"))
                .andExpect(jsonPath("$.status").value(400))
                .andExpect(jsonPath("$.detail").isNotEmpty())
                .andExpect(jsonPath("$.instance").exists());
    }

    @Test
    void creationIsLimitedToThirtyRequestsPerRemoteAddress() throws Exception {
        for (int i = 0; i < 30; i++) {
            create("https://destination.example/limited-" + i, "192.0.2.110");
        }

        mockMvc.perform(post("/api/links")
                        .with(remoteAddress("192.0.2.110"))
                        .contentType("application/json")
                        .content("{\"url\":\"https://destination.example/limited-31\"}"))
                .andExpect(status().isTooManyRequests())
                .andExpect(jsonPath("$.title").value("Too Many Requests"))
                .andExpect(jsonPath("$.status").value(429))
                .andExpect(jsonPath("$.detail").isNotEmpty())
                .andExpect(jsonPath("$.instance").exists());
    }

    @Test
    void rateLimitIsIndependentForDifferentRemoteAddresses() throws Exception {
        for (int i = 0; i < 30; i++) {
            create("https://destination.example/isolation-a-" + i, "192.0.2.111");
        }

        create("https://destination.example/isolation-b", "192.0.2.112");
    }

    @Test
    void omittedExpirationDefaultsToNinetyDaysAndIsPersisted() throws Exception {
        String code = create("https://destination.example/default-expiration", "192.0.2.113");
        Link link = linkRepository.findByCode(code).orElseThrow();

        assertThat(link.getExpiresAt()).isNotNull();
        Instant expectedLowerBound = Instant.now().plus(Duration.ofDays(89));
        Instant expectedUpperBound = Instant.now().plus(Duration.ofDays(91));
        assertThat(link.getExpiresAt()).isBetween(expectedLowerBound, expectedUpperBound);

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", "https://destination.example/default-expiration"));
    }

    @Test
    void oneAndThreeHundredSixtyFiveDayExpirationBoundariesArePersisted() throws Exception {
        String oneDayCode = create("https://destination.example/one-day", "192.0.2.114", "1");
        String oneYearCode = create("https://destination.example/three-six-five", "192.0.2.115", "365");

        Instant oneDayExpiration = linkRepository.findByCode(oneDayCode).orElseThrow().getExpiresAt();
        Instant oneYearExpiration = linkRepository.findByCode(oneYearCode).orElseThrow().getExpiresAt();
        assertThat(Duration.between(Instant.now(), oneDayExpiration)).isBetween(Duration.ofHours(23), Duration.ofHours(25));
        assertThat(Duration.between(Instant.now(), oneYearExpiration)).isBetween(Duration.ofDays(364), Duration.ofDays(366));
    }

    @Test
    void invalidExpirationValuesUseStandardValidationErrorsAndDoNotPersist() throws Exception {
        String[] bodies = {
                "{\"url\":\"https://destination.example/invalid-low\",\"expiresInDays\":0}",
                "{\"url\":\"https://destination.example/invalid-high\",\"expiresInDays\":366}",
                "{\"url\":\"https://destination.example/invalid-fraction\",\"expiresInDays\":1.5}",
                "{\"url\":\"https://destination.example/invalid-string\",\"expiresInDays\":\"1\"}"
        };

        for (int i = 0; i < bodies.length; i++) {
            mockMvc.perform(post("/api/links")
                            .with(remoteAddress("192.0.2." + (120 + i)))
                            .contentType("application/json")
                            .content(bodies[i]))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.title").value("Bad Request"))
                    .andExpect(jsonPath("$.status").value(400))
                    .andExpect(jsonPath("$.detail").isNotEmpty())
                    .andExpect(jsonPath("$.instance").exists());
        }
        assertThat(linkRepository.findByCode("invalid-low")).isEmpty();
    }

    @Test
    void expiredLinkReturnsGoneAndDoesNotRecordAClick() throws Exception {
        Link expired = linkRepository.saveAndFlush(new Link(
                "https://destination.example/expired", "exprd01", Instant.now().minusSeconds(1)));

        mockMvc.perform(get("/exprd01"))
                .andExpect(status().isGone())
                .andExpect(jsonPath("$.title").value("Gone"))
                .andExpect(jsonPath("$.status").value(410))
                .andExpect(jsonPath("$.detail").isNotEmpty())
                .andExpect(jsonPath("$.instance").exists())
                .andExpect(header().doesNotExist("Location"));

        Link reloaded = linkRepository.findById(expired.getId()).orElseThrow();
        assertThat(reloaded.getClickCount()).isZero();
        assertThat(clickEventRepository.countByLinkId(expired.getId())).isZero();
    }

    @Test
    void legacyNullExpirationRemainsRedirectable() throws Exception {
        Link legacy = linkRepository.saveAndFlush(new Link(
                "https://destination.example/legacy", "legacy1"));

        mockMvc.perform(get("/legacy1"))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", legacy.getUrl()));
    }

    @Test
    void privateDestinationIsAcceptedWhenItIsNotTheConfiguredOrigin() throws Exception {
        mockMvc.perform(post("/api/links")
                        .with(remoteAddress("192.0.2.130"))
                        .contentType("application/json")
                        .content("{\"url\":\"http://127.0.0.1:9/private-or-local\"}"))
                .andExpect(status().isCreated());
    }

    private String create(String url, String remoteAddress) throws Exception {
        return create(url, remoteAddress, null);
    }

    private String create(String url, String remoteAddress, String expiresInDays) throws Exception {
        String body = expiresInDays == null
                ? "{\"url\":\"" + url + "\"}"
                : "{\"url\":\"" + url + "\",\"expiresInDays\":" + expiresInDays + "}";
        MvcResult result = mockMvc.perform(post("/api/links")
                        .with(remoteAddress(remoteAddress))
                        .contentType("application/json")
                        .content(body))
                .andExpect(status().isCreated())
                .andReturn();
        return JsonPath.read(result.getResponse().getContentAsString(), "$.code");
    }

    private RequestPostProcessor remoteAddress(String address) {
        return request -> {
            request.setRemoteAddr(address);
            return request;
        };
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkCreationRateLimiterTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.junit.jupiter.api.Test;

class LinkCreationRateLimiterTest {

    @Test
    void admitsThirtyRequestsButRejectsTheThirtyFirstForOneIp() {
        LinkCreationRateLimiter limiter = new LinkCreationRateLimiter(
                Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"), ZoneOffset.UTC));

        for (int i = 0; i < 30; i++) {
            limiter.admit("198.51.100.1");
        }

        assertThatThrownBy(() -> limiter.admit("198.51.100.1"))
                .isInstanceOf(RateLimitExceededException.class);
        limiter.admit("198.51.100.2");
    }

    @Test
    void concurrentAdmissionCannotExceedThirtyRequestsForOneIp() throws Exception {
        LinkCreationRateLimiter limiter = new LinkCreationRateLimiter(Clock.systemUTC());
        int attempts = 100;
        ExecutorService executor = Executors.newFixedThreadPool(10);
        CountDownLatch start = new CountDownLatch(1);
        try {
            List<Future<Boolean>> results = new ArrayList<>();
            for (int i = 0; i < attempts; i++) {
                results.add(executor.submit(() -> {
                    start.await();
                    try {
                        limiter.admit("198.51.100.20");
                        return true;
                    } catch (RateLimitExceededException exception) {
                        return false;
                    }
                }));
            }
            start.countDown();
            long admitted = 0;
            for (Future<Boolean> result : results) {
                if (result.get()) {
                    admitted++;
                }
            }
            assertThat(admitted).isEqualTo(30);
        } finally {
            executor.shutdownNow();
        }
    }
}
"},{"path":"src/test/java/com/example/shortener/CanonicalPublicOriginTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.net.URI;

import org.junit.jupiter.api.Test;

class CanonicalPublicOriginTest {

    @Test
    void unicodeAndPunycodeHostsAreEquivalentForSelfOriginValidation() {
        PublicOriginProvider provider = new PublicOriginProvider(
                "https://bücher.example", "localhost", 8080, false);
        UrlValidator validator = new UrlValidator(provider);

        assertThatThrownBy(() -> validator.validate("https://XN--BCHER-KVA.EXAMPLE./target"))
                .isInstanceOf(InvalidUrlException.class);
        assertThatThrownBy(() -> validator.validate("https://bücher.example/target"))
                .isInstanceOf(InvalidUrlException.class);
        org.assertj.core.api.Assertions.assertThat(provider.matches(URI.create("https://xn--bcher-kva.example/")))
                .isTrue();
    }
}
